import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int k = Integer.parseInt(br.readLine().trim());
        String msg = br.readLine();
        if (msg == null) msg = "";
        if (msg.length() <= k) { System.out.println(msg); return; }
        // Add whole words while "prefix ..." still fits in k characters.
        StringBuilder out = new StringBuilder();
        for (String w : msg.trim().split("\\s+")) {
            int len = out.length() + (out.length() > 0 ? 1 : 0) + w.length() + 4;
            if (len > k) break;
            if (out.length() > 0) out.append(' ');
            out.append(w);
        }
        System.out.println(out.length() == 0 ? "..." : out + " ...");
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	first, _ := in.ReadString('\n')
	k, _ := strconv.Atoi(strings.TrimSpace(first))
	msg, _ := in.ReadString('\n')
	msg = strings.TrimRight(msg, "\r\n")
	if len(msg) <= k {
		fmt.Println(msg)
		return
	}
	// Add whole words while "prefix ..." still fits in k characters.
	out := ""
	for _, w := range strings.Fields(msg) {
		t := w
		if out != "" {
			t = out + " " + w
		}
		if len(t)+4 > k {
			break
		}
		out = t
	}
	if out == "" {
		fmt.Println("...")
	} else {
		fmt.Println(out + " ...")
	}
}
